$(".cs_tab_item").on("click",function(c){let i=$(this).attr("data-index");$(".cs_text_con").each((e,t)=>{e==i?(t.style.display="block",$(".cs_tab_item")[e].classList.add("active")):(t.style.display="none",$(".cs_tab_item")[e].classList.remove("active"))})});setTimeout(function(){var c=document.querySelectorAll(".t4s-swatch__list");if(c.length>0){let i={};Object.keys(c[0].children).forEach((e,t)=>{i[t]=!0});for(let e=0;e<c.length;e++)Object.keys(c[e].children).forEach((t,s)=>{c[e].children[s].className.includes("is--selected")||(i[s]=!1)});Object.keys(i).forEach(e=>{if(i[e]){var t=window.location.href;t.indexOf("?")!=-1&&(t=t.replace(/(\?|#)[^'"]*/,""),window.history.pushState({},0,t))}})}},500);
